fn is_sorted(a: &[i32]) -> bool {
    // Since input is non-empty, safe to iterate starting from index 1
    for i in 1..a.len() {
        // If previous element is greater than current, array is not sorted
        if a[i - 1] > a[i] {
            return false;
        }
    }
    // No decreasing pair found, array is sorted nondecreasing
    true
}